import{_ as o,l as n,o as e,c as i,v as t,p as s,x as r,d as m,i as T,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"ByT5 / 字节级模型","description":"","frontmatter":{"title":"ByT5 / 字节级模型","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/byt5.md","filePath":"llm/byt5.md","lastUpdated":1789023840000}'),d={name:"llm/byt5.md"};function h(B,a,E,c,A,u){const l=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="byt5-字节级模型" tabindex="-1">ByT5 / 字节级模型 <a class="header-anchor" href="#byt5-字节级模型" aria-label="Permalink to &quot;ByT5 / 字节级模型&quot;">​</a></h1><div class="epigraph"><p>标准 Transformer 只需最少改动，就可以直接处理字节序列；代价要用参数量、训练 FLOPs 与推理速度一起量，而不是只看词表大小。</p><footer>—— Xue, Barua, Constant, Al-Rfou, Narang, Kale, Roberts, Raffel, ByT5, TACL 2022</footer></div><p><a href="/llm/tokenizer-design">Tokenizer 设计</a> 把 ByT5 写成 BPE / Unigram 旁边的第三种切分承诺：<a href="/llm/vocab-compression">词表与压缩率</a> 把它当成 \\(V\\approx 256\\) 的下界对照。本篇不重复切分算法，只写 Xue 等人真正改了什么：在 mT5 上拿掉 SentencePiece、把掩码跨度拉到约 20 字节、把编码器做成解码器的三倍深，并把原来锁在词表矩阵里的参数搬进稠密层。实验合同是参数匹配的 mT5，预训练文本量大约只有对照的四分之一。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>子词词表把未登录压成可组合碎片，也把拼写、大小写、形态变化切成完全不同的 ID 序列。未见字符、未见脚本、输入法噪声，都会让同一语义落到不相邻的嵌入上。词表矩阵在多语言模型里可以占掉大半参数——mT5-Base 的嵌入与输出 softmax 约 2.56 亿参数，占总量约 66%——这些行只在对应 token 出现时才被碰到。字节模型把符号空间钉死为 UTF-8 的 256 个值，未登录消失，形态共享变成层内计算而不是词表巧合。</p><p>代价几乎全在长度。mC4 上 mT5 的 SentencePiece 整体压缩率约 4.1 字节/token，语言之间从马耳他语约 2.5 到高棉语约 9.0。同样字符预算下，字节序列更长，自注意力按 token 计仍是二次。过去的字符模型因此常加卷积池化或自适应计算时间。ByT5 的命题更窄：不换架构家族，只问标准编码器–解码器能否把这笔长度税付到可接受。</p><p><span class="marginnote">不要把「无 tokenizer」写成「无预处理」。非法 UTF-8、哨兵字节、填充与句末仍要约定。ByT5 省掉的是一份与训练数据绑定的子词快照，不是全部文本管线。</span></p><h3 id="和-canine、纯字符-lm-不是同一张合同" tabindex="-1">和 CANINE、纯字符 LM 不是同一张合同 <a class="header-anchor" href="#和-canine、纯字符-lm-不是同一张合同" aria-label="Permalink to &quot;和 CANINE、纯字符 LM 不是同一张合同&quot;">​</a></h3><p>Clark 等人的 CANINE 也在字符上做迁移学习，但 CANINE-S 预训练仍用分词器定义掩码目标。早期字符语言模型多半停在语言建模困惑度，很少给出十亿参数以上的生成式预训练。ByT5 要覆盖 mT5 的同一批用途：100 余种语言、text-to-text、分类与生成，并放到 Small 到 XXL（约 1.29×10<sup>10</sup> 参数）这一档。它不是新的高效长序列核，长度税交给普通 Transformer 自己消化。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="相对-mt5-的三处最小改动" tabindex="-1">相对 mT5 的三处最小改动 <a class="header-anchor" href="#相对-mt5-的三处最小改动" aria-label="Permalink to &quot;相对 mT5 的三处最小改动&quot;">​</a></h3><p>ByT5 以 mT5 为底，故意少改，好让对照干净。第一，输入是原始 UTF-8 字节，词表 256，另留填充、句末和一个惯例上的未用 ID；不再训练 SentencePiece。第二，预训练仍是 T5 的跨度破坏，但平均掩码长度从约 3 个子词改成约 20 字节，哨兵复用最后 100 个字节 ID，不另开 100 个新符号。第三，编码器层数设为解码器的三倍：Small 为 12/4，Base 为 18/6，Large 及以上为 36/12。T5 / mT5 的均衡栈在字节上不够用，更重的编码器把「把字节组成词」这件事留在可并行的一侧。</p><p>序列长度仍是 1024，但单位是字节不是子词。预训练 100 万步、每步 \\(2^{20}\\) 个 token，与 mT5 同设定。于是 ByT5 见到的原始文本大约少四倍：同样「token 步数」覆盖的字符更少。作者把这写成数据效率问题，而不是偷偷用更长有效上下文占便宜。</p><h3 id="参数从词表搬进层" tabindex="-1">参数从词表搬进层 <a class="header-anchor" href="#参数从词表搬进层" aria-label="Permalink to &quot;参数从词表搬进层&quot;">​</a></h3><p>去掉大词表后，同名规格的总参数会塌。作者把 \\(d_{\\mathrm{model}}\\) 与 \\(d_{\\mathrm{ff}}\\) 加宽，使五档尺寸与 mT5 参数匹配，并维持 \\(d_{\\mathrm{ff}}/d_{\\mathrm{model}}\\approx 2.5\\)。Small 的词表相关参数从约 85% 降到约 0.3%，Base 从约 66% 降到约 0.1%。小模型上，这些「始终激活」的稠密参数解释了为何 ByT5-Small / Base 在 GLUE、SuperGLUE 上超过参数匹配的 mT5：词表行不再闲置。</p><p>解码器变浅，自回归采样的逐步开销下降，部分对冲字节序列更长。作者预期主场是短到中等输入（数句以内）；文档级摘要会把长度税摊到前向的每一层。</p>',16)),(e(),s(p,null,{default:r(()=>[T(l,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%8E%9F%E5%A7%8B%20UTF-8%20%E6%96%87%E6%9C%AC%22%5D%20--%3E%20B%5B%22256%20%E5%AD%97%E8%8A%82%E5%B5%8C%E5%85%A5%22%5D%0A%20%20B%20--%3E%20E%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%203%C3%97%20%E6%B7%B1%22%5D%0A%20%20E%20--%3E%20D%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%201%C3%97%20%E6%B7%B1%22%5D%0A%20%20D%20--%3E%20Y%5B%22%E5%AD%97%E8%8A%82%E5%BA%8F%E5%88%97%E8%BE%93%E5%87%BA%22%5D%0A%20%20M%5B%22%E8%B7%A8%E5%BA%A6%E6%8E%A9%E7%A0%81%E7%BA%A6%2020%20%E5%AD%97%E8%8A%82%22%5D%20--%3E%20E%0A%20%20M%20--%3E%20D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="字节跨度为什么要更长" tabindex="-1">字节跨度为什么要更长 <a class="header-anchor" href="#字节跨度为什么要更长" aria-label="Permalink to &quot;字节跨度为什么要更长&quot;">​</a></h3><p>掩码三个子词，在英语里往往已经是一个短词或词干加词缀；掩码三个字节则可能只是一个 UTF-8 码点的一部分。平均 20 字节才让重建目标接近「一个短语片段」，编码器必须在局部把字节拼成可生成的跨度。哨兵占用高位字节 ID，则避免为噪声协议再开一套词表版本。</p><p>重编码器的经验结果违背「生成任务该加深解码器」的直觉：分类与生成都受益。作者的解释是，字节级的组合负担主要在理解侧；解码器只要能把已经对齐的表示写成合法字节。实践中模型几乎不产出非法 UTF-8，非法字节在解码时丢弃即可。</p><p><span class="marginnote">压缩率高的语言（泰语、泰卢固语）更偏向 mT5，压缩率低的语言更偏向 ByT5。这不是形态学定理，只是同一窗口里谁看见了更多字符。跨语言比较必须统一用字符或字节做横轴。</span></p><h3 id="噪声与词内任务把归纳偏置暴露出来" tabindex="-1">噪声与词内任务把归纳偏置暴露出来 <a class="header-anchor" href="#噪声与词内任务把归纳偏置暴露出来" aria-label="Permalink to &quot;噪声与词内任务把归纳偏置暴露出来&quot;">​</a></h3><p>合成噪声（随机删字符、重复、全大写、交替大小写、Antspeak 式隔空大写）下，ByT5 掉点小于 mT5；未见噪声比可学习噪声更伤子词模型。TweetQA 这类本来就脏的社交文本上，ByT5 全尺寸超过 mT5。词内任务差距更大：Dakshina 转写、SIGMORPHON 字素到音素与形态屈折，ByT5 全面领先——Small 的屈折准确率 88.3 对 mT5 的 66.5。子词词表把形态切散之后，模型要靠上下文把碎片粘回去；字节模型从第一层就看见字符顺序。</p><p>GLUE / SuperGLUE 上则是小模型 ByT5 更好、大模型 mT5 更好。生成任务（GEM-XSum、TweetQA、DROP）上 ByT5 全尺寸领先。XTREME 的 in-language 设定里，ByT5 在所报任务与尺寸上超过当时的 mT5。这些数字绑定参数匹配与更少预训练文本，不能直接翻译成「解码器大模型该改纯字节」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>ByT5 没有改注意力核。1024 字节窗口对高压缩语言可能只覆盖很短的语义上下文；要做长文档，必须另付长上下文方法，而那些方法的二次或线性复杂度都按更长序列计价。主流解码器后来普遍采用字节级 BPE 而不是纯字节，推理长度税比词表存储更贵，和这篇编码器–解码器的结论并不打架。</p><p>不要把「预训练少看四倍文本仍能打平」写成字节模型数据效率更高。更长序列让每步 FLOPs 更多，模型在同一批字符上算得更久。公平对照要同时报参数、步数、字符吞吐和墙钟。词表矩阵的查找几乎不占 FLOPs，把这些参数搬进 Transformer 层会抬高单步计算；小模型赢在参数利用率，大模型不一定赢在墙钟。</p><p>下游若已经有稳定的子词词表与 KV 工具链，ByT5 的收益集中在噪声、拼写、音译、形态，而不是通用聊天。它证明的是：token-free 不必先发明新架构；它没有证明纯字节是十亿到千亿解码器的默认输入。</p><p><span class="marginnote">复现时不要用子词 tokenizer 去数 ByT5 的上下文。窗口、批量和「训练了多少 token」必须按字节计，否则会把长度税藏进看起来更短的步数里。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ByT5 在 mT5 上做三处最小改动：UTF-8 字节输入、约 20 字节的跨度掩码、编码器深度为解码器三倍。</li><li>大词表参数被搬进稠密层；小模型因此在分类上更占优，因为嵌入行不再闲置。</li><li>预训练按 token 步数对齐时，模型大约少看四倍原始文本；压缩率随语言在约 2.5–9.0 字节/token 之间。</li><li>噪声稳健性与词内任务（转写、音素、屈折）是字节归纳偏置最清楚的证据。</li><li>注意力仍是标准二次核，长输入的墙钟税没有被架构消掉。</li><li>解码器大模型后来仍用字节级 BPE，是推理长度与 KV 缓存的工程选择，不是对这篇实验合同的否定。</li><li>出处：Xue et al.，<em>ByT5: Towards a Token-Free Future with Pre-trained Byte-to-Byte Models</em>，TACL 2022；对照 mT5（Xue et al.，2021）与 T5（Raffel et al.，2020）。</li></ul>',15))])}const k=o(d,[["render",h]]);export{_ as __pageData,k as default};
